import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十二卦 益 风雷益 巽上震下","description":"周易 - 第四十二卦 益 风雷益 巽上震下","frontmatter":{"title":"第四十二卦 益 风雷益 巽上震下","description":"周易 - 第四十二卦 益 风雷益 巽上震下"},"headers":[],"relativePath":"zh/classics/zhouyi/043.md","filePath":"zh/classics/zhouyi/043.md"}'),l={name:"zh/classics/zhouyi/043.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="益" tabindex="-1">益 <a class="header-anchor" href="#益" aria-label="Permalink to “益”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利有攸往，利涉大川。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>益，损上益下，民说无疆，自上下下，其道大光。利有攸往，中正有庆。利涉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>风雷，益；君子以见善则迁，有过则改。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>利用为大作，元吉，无咎。象 曰：元吉无咎，下不厚事也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>或益之，十朋之龟弗克违，永贞吉。王用享于帝，吉。象曰：或益之，自外来也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>益之用凶事，无咎。有孚中行，告公用圭。象曰：益用凶事，固有之也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>中行，告公从。利用为依迁国。象曰：告公从，以益志也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>有孚惠心，勿问元吉。有孚惠我德。象曰：有孚惠心，勿问之矣。惠我德，大得志也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>莫益之，或击之，立心勿恒，凶。象曰：莫益之，偏辞也。或击之，自外来也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
